import { test, expect, Page } from '@playwright/test';
import { loginAs } from './helpers/auth';
import { assertPageHealth } from './helpers/page-health';
import { resolveFirstBookingHref } from './helpers/booking-links';

/**
 * Read a link off the page we are already on instead of hard-coding an id.
 * Detail pages were the ones the health suite skipped, and their ids are
 * generated by the seed, so resolving them keeps the check honest.
 */
async function resolveHref(page: Page, pattern: RegExp, selector = 'a[href]'): Promise<string> {
  const hrefs = await page.locator(selector).evaluateAll((els) =>
    els.map((e) => e.getAttribute('href') || '')
  );
  const found = hrefs.find((h) => pattern.test(h));
  expect(found, `No link matching ${pattern} on ${page.url()}`).toBeTruthy();
  return found as string;
}

test.describe('Phase A: Page Health - Anonymous Role', () => {
  const publicPages = [
    '/',
    '/trips',
    '/destinations',
    '/stations',
    '/credits',
    '/faq',
    '/login',
    '/register',
    '/register/company',
  ];

  for (const url of publicPages) {
    test(`health check for anonymous on ${url}`, async ({ page }) => {
      await assertPageHealth(page, url, {
        allowFailedUrls: url === '/trips' ? ['/api/trips'] : undefined,
      });
    });
  }

  test('interactivity: home search inputs & language toggle', async ({ page }) => {
    await page.goto('/');
    await page.waitForLoadState('domcontentloaded');

    // Language toggle check
    const langBtn = page.locator('button[aria-label*="English"], button[aria-label*="العربية"]').first();
    if (await langBtn.isVisible()) {
      await langBtn.click();
      await page.waitForTimeout(300);
      const langBtn2 = page.locator('button[aria-label*="English"], button[aria-label*="العربية"]').first();
      await langBtn2.click();
      await page.waitForTimeout(300);
    }

    // FAQ accordions on home or /faq
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        await page.goto('/faq', { waitUntil: 'domcontentloaded', timeout: 25_000 });
        break;
      } catch (err) {
        if (attempt === 2) throw err;
        await page.waitForTimeout(2000);
      }
    }
    const firstAccordion = page.locator('button:has-text("كيف"), button:has-text("ما هي")').first();
    if (await firstAccordion.isVisible()) {
      await firstAccordion.click();
      await page.waitForTimeout(200);
      await firstAccordion.click();
    }
  });
});

test.describe('Phase A: Page Health - Customer Role', () => {
  test.beforeEach(async ({ context }) => {
    await loginAs(context, 'customer');
  });

  const customerPages = [
    '/',
    '/trips',
    '/trips/trip-normal-40',
    '/bookings',
    '/profile',
    '/supervisor',
  ];

  for (const url of customerPages) {
    test(`health check for customer on ${url}`, async ({ page }) => {
      await assertPageHealth(page, url);
    });
  }

  // The booking detail, its ticket and its payment page were never covered,
  // even though they are where a long reference or a route heading would
  // widen the page.
  test('health check for customer on the first booking detail and ticket', async ({ page }) => {
    const detail = await resolveFirstBookingHref(page, '/bookings', /^\/bookings\/[^/]+$/, ['big-bk-5']);
    await assertPageHealth(page, detail);
    await assertPageHealth(page, `${detail}/print`);
  });

  test('health check for customer on a payment page when one exists', async ({ page }) => {
    await page.goto('/bookings');
    await page.waitForLoadState('domcontentloaded');
    await page.waitForTimeout(600);
    // A payment page only exists for a booking that is still awaiting payment.
    const pendingTab = page.locator('button[role="tab"]').nth(1);
    if (await pendingTab.count()) {
      await pendingTab.click();
      await page.waitForTimeout(600);
    }
    const pay = page.locator('a[href$="/pay"]').first();
    if (!(await pay.count())) {
      test.skip(true, 'no booking awaiting payment in this fixture');
    }
    const href = await pay.getAttribute('href');
    await assertPageHealth(page, href as string);
  });

  test('interactivity: customer bookings tabs switch', async ({ page }) => {
    await page.goto('/bookings');
    await page.waitForLoadState('domcontentloaded');

    const tabs = ['upcoming', 'pending', 'past', 'cancelled'];
    for (const tab of tabs) {
      const tabButton = page.locator(`button[data-tab="${tab}"], button:has-text("${tab}")`).first();
      if (await tabButton.isVisible()) {
        await tabButton.click();
        await page.waitForTimeout(200);
      }
    }
  });
});

test.describe('Phase A: Page Health - Company Manager Role', () => {
  test.beforeEach(async ({ context }) => {
    await loginAs(context, 'companyAdmin');
  });

  const companyPages = [
    '/company/dashboard',
    '/company/bookings',
    '/company/bookings/new',
    '/company/charter',
    '/company/customers',
    '/company/credit',
    '/company/trip-requests',
    '/company/settings',
  ];

  for (const url of companyPages) {
    test(`health check for company manager on ${url}`, async ({ page }) => {
      await assertPageHealth(page, url);
    });
  }

  // The company booking detail is the page a company manager lives on, and
  // it leads with the booking reference as its heading.
  test('health check for company manager on the first booking detail and ticket', async ({ page }) => {
    const detail = await resolveFirstBookingHref(page, '/company/bookings', /^\/company\/bookings\/[^/]+$/, ['cb-e2e-cancel-test']);
    await assertPageHealth(page, detail);
    await assertPageHealth(page, `${detail}/print`);
  });

  test('interactivity: company customers modal and search', async ({ page }) => {
    await page.goto('/company/customers');
    await page.waitForLoadState('domcontentloaded');

    const searchInput = page.locator('input[placeholder*="بحث"], input[type="search"]').first();
    if (await searchInput.isVisible()) {
      await searchInput.fill('النيل');
      await page.waitForTimeout(300);
      await searchInput.fill('');
    }
  });
});

test.describe('Phase A: Page Health - Super Admin Role', () => {
  test.beforeEach(async ({ context }) => {
    await loginAs(context, 'superAdmin');
  });

  const adminPages = [
    '/admin',
    '/admin/trips',
    '/admin/trips/new',
    '/admin/buses',
    '/admin/bookings',
    '/admin/verify',
    '/admin/cancellations',
    '/admin/companies/pending',
    '/admin/deposit-requests',
    '/admin/credit-report',
    '/admin/charter-bookings',
    '/admin/destinations',
    '/admin/faqs',
    '/admin/users',
    '/admin/stations',
    '/admin/reports',
    '/admin/settings',
    '/admin/audit-log',
    '/admin/supervisor',
  ];

  for (const url of adminPages) {
    test(`health check for super admin on ${url}`, async ({ page }) => {
      await assertPageHealth(page, url);
    });
  }

  // Trip passengers, trip seats and bus layout are dense grids reached from
  // a list, and none of them were health-checked.
  test('health check for super admin on the first trip passengers and seats pages', async ({ page }) => {
    await page.goto('/admin/trips');
    await page.waitForLoadState('domcontentloaded');
    await page.waitForSelector('a[href*="/seats"]', { timeout: 30_000 }).catch(() => {});
    await page.waitForTimeout(600);
    const seats = await resolveHref(page, /^\/admin\/trips\/[^/]+\/seats$/);
    await assertPageHealth(page, seats);
    await assertPageHealth(page, seats.replace(/\/seats$/, '/passengers'));
  });

  test('health check for super admin on the first bus layout page', async ({ page }) => {
    await page.goto('/admin/buses');
    await page.waitForLoadState('domcontentloaded');
    await page.waitForTimeout(600);
    const layoutButton = page.locator('[aria-label="Layout"]').first();
    await expect(layoutButton).toBeVisible();
    await layoutButton.click();
    await page.waitForURL(/\/admin\/buses\/[^/]+\/layout/, { timeout: 25_000 });
    await assertPageHealth(page, page.url());
  });

  test('interactivity: admin filters and tabs on bookings & deposit requests', async ({ page }) => {
    await page.goto('/admin/deposit-requests');
    await page.waitForLoadState('domcontentloaded');

    // Click tabs / filter buttons
    const filterTabs = page.locator('button[data-status], button:has-text("الكل"), button:has-text("معلق")');
    const count = await filterTabs.count();
    for (let i = 0; i < Math.min(count, 3); i++) {
      await filterTabs.nth(i).click();
      await page.waitForTimeout(200);
    }
  });
});
